n.exploreUrl:
@js:

sort = [];
push = (title, url, type1, type2) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: type1,
        layout_flexBasisPercent: type2
    }
});

list = [
    { id: 1, title: "冒险" },
    { id: 2, title: "热血" },
    { id: 3, title: "都市" },
    { id: 4, title: "玄幻" },
    { id: 5, title: "悬疑" },
    { id: 6, title: "耽美" },
    { id: 7, title: "恋爱" },
    { id: 8, title: "生活" },
    { id: 9, title: "搞笑" },
    { id: 10, title: "穿越" },
    { id: 11, title: "修真" },
    { id: 12, title: "后宫" },
    { id: 13, title: "女主" },
    { id: 14, title: "古风" },
    { id: 15, title: "连载" },
    { id: 16, title: "完结" }
];

list.forEach(item => {
    let Url = 'https://m.dumanwu.com/data/sort,';
    let option = {"body":"s="+item.id+"&p={{page}}","method":"POST"};
    let url = Url + JSON.stringify(option);
    push(item.title, url, 1, 0.25); 
});

JSON.stringify(sort)

ruleToc.chapterList:
@js:
aList=java.getElements('.chaplist-box@a');
list=[]
for(i in aList){list.push({"title":aList[i].text(),"url":aList[i].attr('href')})}; 
var id = baseUrl.match(/com\/(\w+)/)[1];
option={"method": "POST","body": "id=" +id}
url="https://m.dumanwu.com/morechapter"
ls=JSON.parse(java.ajax(url+','+JSON.stringify(option))).data 
for(i in ls){
url = baseUrl + "/" + ls[i].chapterid + ".html"
list.push({"title":ls[i].chaptername,"url":url})}
list.reverse()

